namespace ghidra.features.bsim.query.file;





using org.apache.commons.collections4.iterators;

using ghidra.features.bsim.query;
using ghidra.features.bsim.query.BSimServerInfo;
using ghidra.util;

public class VectorStore : Iterable<VectorStoreEntry> {

	private BSimServerInfo serverInfo;
	private Map<Long, VectorStoreEntry> vectors = null;

	public VectorStore(BSimServerInfo serverInfo) {
		if (serverInfo.getDBType() != DBType.file) {
			throw new IllegalArgumentException("Unsupported DBType");
		}
		this.serverInfo = serverInfo;
	}

	private void init() {
		if (vectors == null) {
			try {
				loadVectors();
			}
			catch (SQLException e) {
				// TODO: do we need different interface to properly convey error?
				Msg.error(this, "Failed to load vectors for " + serverInfo + ": " + e.getMessage());
			}
		}
	}

	/* @SuppressWarnings("unchecked") */
	/* @Override */
	public Iterator<VectorStoreEntry> iterator() {
		init();
		if (vectors == null) {
			return EmptyIterator.INSTANCE;
		}
		return vectors.values().iterator();
	}

	public VectorStoreEntry getVectorById(long id) {
		init();
		if (vectors == null) {
			return null;
		}
		return vectors.get(id);
	}

	private void loadVectors()
    {
		// NOTE: assume file DB (see constructor above)
		using (H2FileFunctionDatabase fnDb = new H2FileFunctionDatabase(serverInfo))
{
			if (!fnDb.initialize()) {
				throw new SQLException(fnDb.getLastError().message);
			}
			vectors = fnDb.readVectorMap();
		}
	}

	public void invalidate() {
		vectors = null;
	}

	public void update(VectorStoreEntry entry) {
		if (vectors != null) {
			vectors.put(entry.id(), entry);
		}
	}

	public void update(long id, int count) {
		if (vectors == null) {
			return;
		}
		VectorStoreEntry entry = vectors.get(id);
		if (entry == null) {
			invalidate();
		}
		else {
			vectors.put(id, new VectorStoreEntry(id, entry.vec(), count, entry.selfSig()));
		}
	}

	public void delete(long id) {
		if (vectors != null) {
			vectors.remove(id);
		}
	}

}
